  function sample(mean,std){
    var x=new Array(n);
    for(var j=0;j<n;j++){
      var u=Math.random();
      if(u<1e-12)u=1e-12;
      var v=Math.random();
      var g=Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
      x[j]=mean[j]+std[j]*g;
      if(Math.random()<0.015)x[j]=LO[j]+Math.random()*(HI[j]-LO[j]);
