  }

  function runES(start,frac,maxTrials,lambda,mu,genLimit){
    var targetLeft=lab.trialsLeft()-maxTrials;
    if(targetLeft<0)targetLeft=0;
    var mean=clampParams(start.slice());
    var sig=new Array(n);
    for(var j=0;j<n;j++)sig[j]=Math.max((HI[j]-LO[j])*frac,(HI[j]-LO[j])*0.001);
    var localBest=evaluate(mean);
    var noImp=0;

    for(var gen=0;gen<genLimit&&lab.trialsLeft()>targetLeft;gen++){
      var pop=[];
      if(lab.trialsLeft()>targetLeft)pop.push(evaluate(mean));
      for(var k=1;k<lambda&&lab.trialsLeft()>targetLeft;k++){
        pop.push(evaluate(sample(mean,sig)));
      }
      if(pop.length===0)break;
      pop.sort(function(a,b){return b.score-a.score;});
      if(pop[0].score>localBest.score+1e-9){localBest=pop[0];noImp=0;}else noImp++;

      var e=Math.min(mu,pop.length);
      var wsum=0;
      var wArr=new Array(e);
      var newMean=new Array(n);
      for(var j2=0;j2<n;j2++)newMean[j2]=0;
      for(var q=0;q<e;q++){
        var w=Math.exp(-0.5*q);
        wArr[q]=w;
        wsum+=w;
        var xx=pop[q].x;
        for(var j3=0;j3<n;j3++)newMean[j3]+=w*xx[j3];
      }
      for(var j4=0;j4<n;j4++)newMean[j4]/=wsum;
      newMean=clampParams(newMean);

      var varArr=new Array(n);
      for(var j5=0;j5<n;j5++)varArr[j5]=0;
      for(var q2=0;q2<e;q2++){
        var w2=wArr[q2];
        var xq=pop[q2].x;
        for(var j6=0;j6<n;j6++){
