  for(var i=0;i<2;i++){
    var off=(i===0)?0:legOff;
    var s=phaseBase+phaseOff+off;
    s=s-Math.floor(s);
    var x,hipTraj,kneeExtra,swingW;
    if(s<d){
      x=(d>1e-6)?s/d:0;
      hipTraj=Math.cos(Math.PI*x);
      kneeExtra=-kSt*Math.sin(Math.PI*x);
      swingW=0;
    }else{
      var den=1-d;
      if(den<1e-6)den=1e-6;
      x=(s-d)/den;
      hipTraj=-Math.cos(Math.PI*x);
      kneeExtra=-kSw*Math.sin(Math.PI*x);
      swingW=Math.sin(Math.PI*x);
    }
    var stanceW=1-swingW;

    var hipTarget=h0+hA*hipTraj;
    var kneeTarget=kBase+kneeExtra;

    hipTarget+=pv(p,19)*Math.sin(4*Math.PI*s+2*Math.PI*pv(p,20));
    hipTarget+=pv(p,16)*(vx-vdes)*(0.2+0.8*swingW);
    hipTarget+=pv(p,24)*hh*swingW;
    hipTarget+=pv(p,26)*theta*swingW+pv(p,27)*spin*swingW;
    hipTarget+=pv(p,39)*slope*swingW;

    kneeTarget-=pv(p,21)*hh*(0.25+0.75*swingW);
    kneeTarget-=pv(p,28)*swingW;
    kneeTarget+=pv(p,29)*vy*stanceW;
    kneeTarget+=pv(p,30)*(0.78-height)*stanceW;
    if(hh4>0.001&&swingW>0.02)kneeTarget-=pv(p,42)*hh4*swingW;

    var foot=(i===0)?footA:footB;
    if(swingW>0.05&&foot>0.5)kneeTarget-=pv(p,22)*swingW;
    if(foot>0.5&&swingW>0.1)hipTarget-=pv(p,31)*swingW;
    if(foot>0.5&&swingW>0.05)hipTarget-=pv(p,38)*swingW;
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,32)*(x-0.3);
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,43)*(x-0.3);

    var cg=pv(p,34);
    if(cg>0&&swingW>0.02&&hh>0.005){
      var footDrop=0.38*Math.cos(hipTarget)+0.43*Math.cos(hipTarget+kneeTarget);
      var hipH=height-0.255*Math.cos(theta);
      var clear=hipH-footDrop;
      var want=pv(p,41)+0.9*hh;
      if(clear<want){
        var add=(want-clear)*cg;
        if(add>0.8)add=0.8;
        kneeTarget-=add;
        hipTarget-=pv(p,40)*add;
      }
    }

    hipTarget=clampv(hipTarget,-0.88,1.18);
    kneeTarget=clampv(kneeTarget,-1.65,-0.055);

    var hipT=ramp*hipTarget+(1-ramp)*0.0;
    var kneeT=ramp*kneeTarget+(1-ramp)*(-0.06);

    var qHip=(i===0)?+obs[5]:+obs[10];
    var qdHip=(i===0)?+obs[6]:+obs[11];
    var qKnee=(i===0)?+obs[7]:+obs[12];
    var qdKnee=(i===0)?+obs[8]:+obs[13];
    if(!isFinite(qHip))qHip=0;
    if(!isFinite(qdHip))qdHip=0;
    if(!isFinite(qKnee))qKnee=-0.06;
    if(!isFinite(qdKnee))qdKnee=0;

    var prevH=mem.prevH[i],prevK=mem.prevK[i];
    var velH=0,velK=0;
    if(prevH!==null&&prevH!==undefined)velH=(hipT-prevH)*60;
    if(prevK!==null&&prevK!==undefined)velK=(kneeT-prevK)*60;
    if(!isFinite(velH))velH=0;
    if(!isFinite(velK))velK=0;
    velH=clampv(velH,-25,25);
    velK=clampv(velK,-25,25);
    mem.prevH[i]=hipT;
    mem.prevK[i]=kneeT;

    var hipKp=Math.max(0,pv(p,12));
    var hipKd=Math.max(0,pv(p,13));
    var kneeKp=Math.max(0,pv(p,14));
    var kneeKd=Math.max(0,pv(p,15));

    var tauH=hipKp*(hipT-qHip)+hipKd*(velH-qdHip);
    var tauK=kneeKp*(kneeT-qKnee)+kneeKd*(velK-qdKnee);

    var footW=(foot>0.5)?1:0.2;
    tauH+=balBase*footW;

    raw[2*i]=clampv(tauH,-1,1);
    raw[2*i+1]=clampv(tauK,-1,1);
  }

  return [signs[0]*raw[0],signs[1]*raw[1],signs[2]*raw[2],signs[3]*raw[3]];
}

function learn(lab){
  var n=N;
  var cache={};
  var seenItems=[];
  var best=null;

  function keyOf(x){
    var s="";
    for(var i=0;i<n;i++)s+=Math.round(x[i]*50000)+",";
    return s;
  }

  function evaluate(x){
    x=clampParams(x);
    var key=keyOf(x);
    if(cache[key])return cache[key];
    if(lab.trialsLeft()<=0){
      return {x:x.slice(),score:-1e9,distance:0,outcome:"none",time:0,energy:0};
    }
    var res;
    try{
      res=lab.trial(x.slice());
    }catch(e){
      res={distance:0,outcome:"error",time:0,energy:0};
    }
    if(!res)res={};
    var dist=Number(res.distance);
    if(!isFinite(dist)||dist<0)dist=Math.max(0,isFinite(dist)?dist:0);
    var outcome=String(res.outcome||"");
    var time=Number(res.time);
    if(!isFinite(time)||time<0)time=0;
    if(time>10)time=10;
    var energy=Number(res.energy);
    if(!isFinite(energy))energy=0;

    var score;
    if(outcome==="invalid"||outcome==="error"){
      score=-1000000+Math.max(0,dist);
    }else{
      score=dist+0.04*time;
      if(outcome==="finished")score+=0.6;
      if(time>=9.95)score+=0.6;
      if(outcome==="fell")score-=Math.max(0,10-time)*0.18;
      if(time>9.7&&dist>0.1)score+=0.1;
      if(!isFinite(score))score=-1e9;
    }

    var item={
      x:x.slice(),
      score:score,
      distance:dist,
      outcome:outcome,
      time:time,
      energy:energy
    };
    cache[key]=item;
    seenItems.push(item);
    if(!best||item.score>best.score)best=item;
    return item;
  }

  function mk(base,o){
    var x=(base||DEF).slice();
    for(var k in o){
      if(o.hasOwnProperty(k)){
        var idx=+k;
        if(idx>=0&&idx<n)x[idx]=o[k];
      }
    }
    return clampParams(x);
  }

  function gauss(){
    var u=Math.random();
    if(u<1e-12)u=1e-12;
    var v=Math.random();
    return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  }

  function sample(mean,sig,mask){
    var x=new Array(n);
    for(var j=0;j<n;j++){
      if(sig[j]>1e-12&&(!mask||mask[j]))x[j]=mean[j]+sig[j]*gauss();
      else x[j]=mean[j];
    }
    if(Math.random()<0.025){
      var inds=[];
      for(var j2=0;j2<n;j2++){
        if(!mask||mask[j2])inds.push(j2);
      }
      if(inds.length){
        var jj=inds[Math.floor(Math.random()*inds.length)];
        x[jj]=LO[jj]+Math.random()*(HI[jj]-LO[jj]);
      }
    }
    return clampParams(x);
  }

  function runCEM(start,frac,maxTrials,lambda,mu,genLimit,mask){
    if(lab.trialsLeft()<=0)return null;
    var targetLeft=lab.trialsLeft()-maxTrials;
    if(targetLeft<0)targetLeft=0;
    var mean=clampParams(start.slice());
    var sig=new Array(n);
    for(var j=0;j<n;j++){
      var range=HI[j]-LO[j];
      sig[j]=Math.max(range*frac,range*0.001);
      if(mask&&!mask[j])sig[j]=0;
    }
    var localBest=evaluate(mean);
    var noImp=0;

    for(var gen=0;gen<genLimit&&lab.trialsLeft()>targetLeft;gen++){
      var pop=[];
      if(lab.trialsLeft()>targetLeft)pop.push(evaluate(mean));
      for(var k=1;k<lambda&&lab.trialsLeft()>targetLeft;k++){
        pop.push(evaluate(sample(mean,sig,mask)));
      }
      if(!pop.length)break;
      pop.sort(function(a,b){return b.score-a.score;});
      var improved=pop[0].score>localBest.score+1e-9;
      if(pop[0].score>localBest.score+1e-9)localBest=pop[0];

      var e=Math.min(mu,pop.length);
      var newMean=new Array(n);
      var varArr=new Array(n);
      var weights=new Array(e);
      for(var j1=0;j1<n;j1++){newMean[j1]=0;varArr[j1]=0;}
      var wsum=0;
      for(var q=0;q<e;q++){
        var w=Math.exp(-0.5*q);
        weights[q]=w;
        wsum+=w;
        var xx=pop[q].x;
        for(var j2=0;j2<n;j2++)newMean[j2]+=w*xx[j2];
      }
      for(var j3=0;j3<n;j3++)newMean[j3]/=wsum;
      newMean=clampParams(newMean);

      for(var q2=0;q2<e;q2++){
        var w2=weights[q2];
        var xq=pop[q2].x;
        for(var j4=0;j4<n;j4++){
          var dd=xq[j4]-newMean[j4];
          varArr[j4]+=w2*dd*dd;
        }
      }

      for(var j5=0;j5<n;j5++){
        if(!mask||mask[j5]){
          var range2=HI[j5]-LO[j5];
          var vv=Math.sqrt(Math.max(0,varArr[j5]/wsum));
          var ns=0.65*vv+0.35*sig[j5];
          var minS=Math.max(0.0001,range2*0.002);
          var maxS=Math.max(minS,range2*0.6);
          sig[j5]=clampv(ns,minS,maxS);
          mean[j5]=0.4*newMean[j5]+0.6*pop[0].x[j5];
        }else{
          mean[j5]=newMean[j5];
          sig[j5]=0;
        }
      }
      mean=clampParams(mean);

      if(improved){
        noImp=0;
      }else{
        noImp++;
        for(var j6=0;j6<n;j6++){
          if((!mask||mask[j6])&&sig[j6]>0){
            var r3=HI[j6]-LO[j6];
            sig[j6]=Math.max(r3*0.002,sig[j6]*0.88);
          }
        }
      }

      if(noImp>=5){
        mean=localBest.x.slice();
        for(var j7=0;j7<n;j7++){
          if(!mask||mask[j7]){
            var r4=HI[j7]-LO[j7];
            sig[j7]=Math.min(r4*0.5,Math.max(r4*0.004,sig[j7]*1.5));
          }
        }
        noImp=0;
      }
    }
    return localBest;
  }

  function coordinateSearch(start,maxTrials,stepFrac,maxSweeps,mask){
    if(lab.trialsLeft()<=0)return null;
    var targetLeft=lab.trialsLeft()-maxTrials;
    if(targetLeft<0)targetLeft=0;
    var x=clampParams(start.slice());
    var cur=evaluate(x);
    var step=new Array(n);
    for(var j=0;j<n;j++){
      var rr=HI[j]-LO[j];
      step[j]=Math.max(rr*stepFrac,rr*0.001);
      if(mask&&!mask[j])step[j]=0;
    }
    var sweeps=0;
    while(lab.trialsLeft()>targetLeft&&sweeps<maxSweeps){
      var inds=[];
      for(var j2=0;j2<n;j2++)if(step[j2]>0)inds.push(j2);
      for(var a=inds.length-1;a>0;a--){
        var b=Math.floor(Math.random()*(a+1));
        var tmp=inds[a];inds[a]=inds[b];inds[b]=tmp;
      }
      var improvedAny=false;
      for(var idx=0;idx<inds.length&&lab.trialsLeft()>targetLeft;idx++){
        var jj=inds[idx];
        var bestIt=null,bestX=null;
        var signs=(Math.random()<0.5)?[1,-1]:[-1,1];
        for(var ss=0;ss<2&&lab.trialsLeft()>targetLeft;ss++){
          var y=x.slice();
          var nv=x[jj]+signs[ss]*step[jj];
          if(nv<LO[jj])nv=LO[jj];
          if(nv>HI[jj])nv=HI[jj];
          if(Math.abs(nv-x[jj])<1e-12)continue;
          y[jj]=nv;
          y=clampParams(y);
          var it=evaluate(y);
          if(!bestIt||it.score>bestIt.score){bestIt=it;bestX=y;}
        }
        if(bestIt&&bestIt.score>cur.score+1e-9){
          x=clampParams(bestX);
          cur=bestIt;
          improvedAny=true;
          var rjj=HI[jj]-LO[jj];
          step[jj]=Math.min(rjj*0.5,step[jj]*1.15);
        }else{
          step[jj]*=0.8;
        }
      }
      if(!improvedAny){
        for(var j3=0;j3<n;j3++)if(step[j3]>0)step[j3]*=0.7;
        var maxRatio=0;
        for(var j4=0;j4<n;j4++){
          var r5=HI[j4]-LO[j4];
          if(r5>0)maxRatio=Math.max(maxRatio,step[j4]/r5);
        }
        if(maxRatio<0.0025)break;
      }
      sweeps++;
    }
    return cur;
  }

  function getTop(count){
    var arr=seenItems.slice().sort(function(a,b){return b.score-a.score;});
    var out=[];
    for(var a=0;a<arr.length&&out.length<count;a++){
      var it=arr[a];
      var unique=true;
      for(var b=0;b<out.length;b++){
        var o=out[b];
        var dsum=0;
        for(var j=0;j<n;j++){
          var d=(it.x[j]-o.x[j])/(HI[j]-LO[j]+1e-9);
          dsum+=d*d;
          if(dsum>0.08)break;
        }
        if(dsum<0.08){unique=false;break;}
      }
      if(unique)out.push(it);
    }
    return out;
  }

  var A1=DEF.slice();
  A1[0]=1.8;A1[1]=0;A1[2]=0.55;A1[3]=0.38;A1[4]=0.02;A1[5]=1.0;A1[6]=0.30;A1[7]=0.19;A1[8]=0.5;A1[9]=0.9;A1[10]=0.10;A1[11]=-0.15;A1[12]=1.5;A1[13]=0.15;A1[14]=1.8;A1[15]=0.20;A1[16]=0.08;A1[17]=0.15;A1[18]=2.0;A1[19]=0.0;A1[20]=0.0;A1[21]=1.8;A1[22]=0.6;A1[23]=1.0;A1[24]=0.6;A1[25]=0.2;
  A1=clampParams(A1);

  var OLDX=DEF.slice();
  var OLDARR=[2.248757964532036,0.22489671356233115,-0.4651697523833812,0.38990217842369634,0.26636523739884704,0.567425203431214,0.3268441875841595,-0.21486421614560086,0.49514943122107347,0.3900091470283445,0.039157236149931426,-0.18946397105138021,3.0910427945770853,0.09046646396228597,1.3921510356596358,0.5622862255582213,-0.12510650138142773,0.09135689087032488,1.6989988015687103,-0.09813027530285129,0.8082310754813673,1.3744253231829437,0.6149620076503435,-1.1826706470376152,0.32728443484507164,0.37421231515283165];
  for(var oi=0;oi<26;oi++)OLDX[oi]=OLDARR[oi];
  for(var oj=26;oj<36;oj++)OLDX[oj]=0;
  OLDX=clampParams(OLDX);

  evaluate(DEF);
  evaluate(A1);
  evaluate(OLDX);
  evaluate(mk(DEF,{34:0,35:0}));
  evaluate(mk(DEF,{18:1.2,36:1.0,37:0.2,21:2.0,22:1.0,24:0.2,25:0.5,34:1.0}));
  evaluate(mk(DEF,{9:1.2,12:4.5,23:-1.0,36:1.5,34:0.8}));
  evaluate(mk(A1,{2:-0.55,8:0.5,21:1.6,22:0.6,24:0.2,25:0.4,34:0.8,35:-0.1,36:0.8,40:0.15,41:0.01}));
  evaluate(mk(A1,{2:0.55,8:0,23:1.0,34:0.8}));
  evaluate(mk(DEF,{8:0,11:-0.1,18:2.0,34:1.2,35:0}));
  evaluate(mk(DEF,{8:0.5,11:-0.3,18:2.4,21:2.4,22:1.0,24:0.3,25:0.6,34:1.2}));
  evaluate(mk(DEF,{23:1.18,2:-0.465}));
  evaluate(mk(DEF,{3:0.45,5:0.9,6:0.4,8:0.5}));
  evaluate(mk(DEF,{18:1.5,23:-1.0,34:1.0,36:1.2,37:0.1,40:0.2}));
  evaluate(mk(DEF,{21:2.2,22:1.2,24:0.25,25:0.5,34:1.2,36:1.0}));

  for(var ri=0;ri<80;ri++){
    var xx;
    if(ri<52){
      var base=(ri%3===0)?DEF:((ri%3===1)?A1:OLDX);
      xx=base.slice();
      for(var rj=0;rj<26;rj++){
        if(Math.random()<0.55)xx[rj]+=gauss()*(HI[rj]-LO[rj])*0.22;
      }
      for(var rk=26;rk<n;rk++){
        if(Math.random()<0.22)xx[rk]+=gauss()*(HI[rk]-LO[rk])*0.20;
      }
    }else{
      xx=DEF.slice();
      xx[0]=0.8+Math.random()*3.2;
      xx[1]=(Math.random()-0.5)*0.7;
      if(ri%5===0)xx[2]=-(0.20+Math.random()*0.9);
      else xx[2]=(Math.random()<0.18?(0.20+Math.random()*0.7):-(0.20+Math.random()*0.9));
      xx[3]=0.20+Math.random()*0.55;
      xx[4]=Math.random()*0.55;
      xx[5]=0.2+Math.random()*1.5;
      xx[6]=Math.random()*0.8;
      xx[7]=(Math.random()-0.5)*0.8;
      xx[8]=(ri%4===0)?0:((ri%4===1)?0.5:Math.random()*0.5);
      xx[9]=0.2+Math.random()*3.0;
      xx[10]=Math.random()*0.3;
      xx[11]=-0.65+Math.random()*0.55;
      xx[12]=0.8+Math.random()*4.2;
      xx[13]=0.02+Math.random()*0.5;
      xx[14]=0.8+Math.random()*3.2;
      xx[15]=0.05+Math.random()*0.8;
      xx[16]=(Math.random()-0.5)*0.7;
      xx[17]=Math.random()*0.5;
      xx[18]=0.8+Math.random()*3.0;
      xx[19]=(Math.random()-0.5)*0.35;
      xx[20]=Math.random();
      xx[21]=0.2+Math.random()*2.8;
      xx[22]=Math.random()*1.8;
      xx[23]=(Math.random()<0.35?1:-1)*(0.25+Math.random()*1.2);
      xx[24]=(Math.random()-0.5)*0.5;
      xx[25]=Math.random()*0.9;
      xx[34]=0.2+Math.random()*1.6;
      xx[35]=(Math.random()-0.5)*0.45;
      xx[36]=Math.random()*2.0;
      xx[37]=(Math.random()-0.3)*0.6;
      xx[38]=Math.random()*0.5;
      xx[39]=(Math.random()-0.5)*0.6;
      xx[40]=Math.random()*0.5;
      xx[41]=Math.random()*0.08;
      xx[42]=Math.random()*1.0;
      xx[43]=Math.random()*0.5;
    }
    xx=clampParams(xx);
    evaluate(xx);
  }

  var initialBest=best?best.x.slice():DEF.slice();
  var coreMask=new Array(n);
  for(var cm=0;cm<26;cm++)coreMask[cm]=true;

  var topPre=getTop(10);
  var start2=initialBest;
  if(topPre.length>1)start2=topPre[1].x.slice();
  else if(topPre.length>0)start2=topPre[0].x.slice();

  runCEM(initialBest,0.22,210,16,6,55,coreMask);
  runCEM(start2,0.32,110,16,6,35,coreMask);
  runCEM(best?best.x:DEF,0.12,170,16,6,60,null);
  coordinateSearch(best?best.x:DEF,150,0.08,12,null);
  runCEM(best?best.x:DEF,0.035,100,14,5,45,null);

  var robustBest=null;
  var robustMetric=-1e18;
  var topCands=getTop(12);
  for(var ci=0;ci<topCands.length&&lab.trialsLeft()>12;ci++){
    var cand=topCands[ci];
    var sum=cand.score;
    var mn=cand.score;
    var cnt=1;
    for(var q=0;q<4&&lab.trialsLeft()>12;q++){
      var y=cand.x.slice();
      var frac=(q%2===0)?0.025:0.05;
      for(var j=0;j<n;j++){
        if(Math.random()<0.35)y[j]+=gauss()*(HI[j]-LO[j])*frac;
      }
      if(q===0)y[18]+=0.12;
      if(q===1)y[18]-=0.12;
      if(q===2){
        y[0]*=(1+0.02*(Math.random()<0.5?1:-1));
        y[7]+=0.015*(Math.random()<0.5?1:-1);
      }
      if(q===3){
        y[9]*=(1+0.03*(Math.random()<0.5?1:-1));
        y[12]*=(1+0.03*(Math.random()<0.5?1:-1));
      }
      y=clampParams(y);
      var it=evaluate(y);
      sum+=it.score;
      cnt++;
      if(it.score<mn)mn=it.score;
    }
    var avg=sum/cnt;
    var metric=0.55*cand.score+0.35*avg+0.10*mn;
    if(metric>robustMetric){
      robustMetric=metric;
      robustBest=cand;
    }
  }

  var chosen=robustBest?robustBest.x.slice():(best?best.x.slice():DEF.slice());
  if(best&&robustBest&&best.score>robustBest.score+1.2)chosen=best.x.slice();

  if(lab.trialsLeft()>18){
    var fine=coordinateSearch(chosen,Math.min(45,lab.trialsLeft()-10),0.02,5,null);
    if(fine&&(!robustBest||fine.score>robustBest.score+0.15))chosen=fine.x.slice();
  }

  var centerScore=evaluate(chosen).score;
  var guard=0;
  while(lab.trialsLeft()>0&&guard<700){
    guard++;
    var z=chosen.slice();
    var cf=0.04*Math.pow(0.995,guard);
    if(cf<0.008)cf=0.008;
    for(var zj=0;zj<n;zj++){
