    clampv((Math.abs(theta)-0.50)/0.45,0,1),
    clampv((0.58-height)/0.22,0,1),
    clampv((Math.abs(spin)-2.2)/2.0,0,1)
  );

  var freq=Math.max(0.05,pv(p,0)*(1-0.045*endur-0.025*late));
  var phaseOff=pv(p,7);
  var d=clampv(pv(p,3),0.15,0.85);
  var h0=pv(p,1);
  var hA=pv(p,2);
  if(Math.abs(hA)<0.12)hA=(hA<0?-0.12:0.12);
  var vdes=pv(p,18)-pv(p,37)*endur-0.10*endur-0.08*late*endur-0.12*obstSlow;
