  var kBase=-0.06-Math.max(0,pv(p,4));
  var kSw=Math.max(0,pv(p,5));
  var kSt=Math.max(0,pv(p,6));
  var legOff=pv(p,8);

  var ramp=clampv(te/0.65,0,1);
