        var bestIt=null,bestX=null;
        var signs=(Math.random()<0.5)?[1,-1]:[-1,1];
        for(var ss=0;ss<2&&lab.trialsLeft()>target;ss++){
          var nv=clampv(x[jj]+signs[ss]*step[jj],LO[jj],HI[jj]);
          if(Math.abs(nv-x[jj])<1e-12)continue;
          var y=x.slice();
          y[jj]=nv;
          y=clampParams(y);
          var it=evaluate(y);
          if(!bestIt||it.score>bestIt.score){bestIt=it;bestX=y;}
        }
        if(bestIt&&bestIt.score>cur.score+1e-9){
          x=bestX;
          cur=bestIt;
          improvedAny=true;
          step[jj]=Math.min((HI[jj]-LO[jj])*0.5,step[jj]*1.12);
        }else{
          step[jj]*=0.78;
        }
      }
      if(!improvedAny){
        for(var j3=0;j3<n;j3++)step[j3]*=0.65;
        var mx=0;
        for(var j4=0;j4<n;j4++){
          var rr=HI[j4]-LO[j4];
          if(rr>0)mx=Math.max(mx,step[j4]/rr);
        }
        if(mx<0.002)break;
      }
      sweeps++;
    }
    return cur;
  }

  function getTop(count,stableOnly){
    var arr=seenItems.slice();
    if(stableOnly){
      arr=arr.filter(function(it){return it.stable;});
    }
    arr.sort(function(a,b){return b.score-a.score;});
    var out=[];
    for(var a=0;a<arr.length&&out.length<count;a++){
      var it=arr[a];
      var unique=true;
      for(var b=0;b<out.length;b++){
        var dsum=0;
        for(var j=0;j<n;j++){
          var d=(it.x[j]-out[b].x[j])/(HI[j]-LO[j]+1e-9);
          dsum+=d*d;
          if(dsum>0.075)break;
        }
        if(dsum<0.075){unique=false;break;}
      }
      if(unique)out.push(it);
    }
    return out;
  }

  evaluate(B3);
  evaluate(OLD);
  evaluate(D3);
  evaluate(HYB);
  evaluate(HYB2);
  evaluate(mk(B3,{34:0.7,40:0.12,41:0.01,36:0.25}));
  evaluate(mk(OLD,{34:0.7,40:0.12,41:0.01,35:0.5,36:0.25}));

  function R(max){return Math.min(max,Math.max(0,lab.trialsLeft()-35));}

  runES(B3,R(120),0.090,12,5);
  runES(OLD,R(120),0.090,12,5);
  runES(D3,R(85),0.100,10,4);
  runES(HYB,R(65),0.100,10,4);

  var mid=getTop(1,true);
  if(!mid.length)mid=getTop(1,false);
  var x0=mid.length?mid[0].x.slice():(best?best.x.slice():B3.slice());

  runES(x0,R(165),0.055,14,6);
  coord(best?best.x.slice():x0,R(135),0.050,10);
  runES(best?best.x.slice():x0,R(125),0.030,14,6);
  coord(best?best.x.slice():x0,R(95),0.025,8);

  var cands=getTop(14,true);
  if(!cands.length)cands=getTop(14,false);
  var robustBest=null;
  var robustMetric=-1e18;

  for(var ci=0;ci<cands.length&&lab.trialsLeft()>5;ci++){
    var cand=cands[ci];
    var sum=cand.score;
    var mn=cand.score;
    var cnt=1;
    for(var q=0;q<3&&lab.trialsLeft()>5;q++){
      var y=cand.x.slice();
      var frac=(q===0)?0.025:0.045;
      for(var j=0;j<n;j++){
        if(Math.random()<0.27)y[j]+=gauss()*(HI[j]-LO[j])*frac;
      }
      if(q===0){y[18]+=0.08;y[3]+=0.01;}
      if(q===1){y[18]-=0.10;y[3]-=0.01;}
      if(q===2){y[7]+=0.02;y[25]+=0.02;y[40]+=0.01;}
      y=clampParams(y);
      var it=evaluate(y);
      sum+=it.score;
      cnt++;
      if(it.score<mn)mn=it.score;
    }
    var avg=sum/cnt;
    var metric=0.55*cand.score+0.30*avg+0.15*mn;
    if(cand.stable)metric+=0.20;
    if(metric>robustMetric){
      robustMetric=metric;
      robustBest=cand;
    }
  }

  var seedItems=[evaluate(B3),evaluate(OLD),evaluate(D3)];
  var seedBest=seedItems[0];
  for(var si=1;si<seedItems.length;si++){
    if(seedItems[si].score>seedBest.score)seedBest=seedItems[si];
  }

  var chosen=robustBest?robustBest.x.slice():(cands.length?cands[0].x.slice():(best?best.x.slice():B3.slice()));
  var chosenItem=robustBest||cands[0]||best;
  if(!chosenItem||seedBest.score>seedBest.score-1){
    if(seedBest&&(!chosenItem||seedBest.score+0.20>chosenItem.score)){
      chosen=seedBest.x.slice();
    }
  }
  if(seedBest&&chosenItem&&chosenItem.score<seedBest.score+0.20){
    chosen=seedBest.x.slice();
  }

  return clampParams(chosen);
}

function clampv(x,a,b){x=+x;if(!isFinite(x))x=0;return x<a?a:(x>b?b:x);}
var N=44;
var DEF=[2.248757964532036,0.22489671356233115,-0.4651697523833812,0.38990217842369634,0.315565237398847,0.567425203431214,0.3268441875841595,-0.21486421614560086,0.5,0.3900091470283445,0.039157236149931426,-0.18946397105138021,3.7634427945770854,0.09046646396228597,1.3921510356596358,0.5622862255582213,-0.12510650138142773,0.09135689087032488,1.6989988015687103,-0.09813027530285129,0.8082310754813673,1.661425323182944,0.6149620076503435,-1.1826706470376152,0.12556443484507163,0.37421231515283165,0,0,0,0,0,0,0,0,0.9714999999999999,-0.13,0.8,0,0,0,0.15,0.01,0,0];
var LO=[0.3,-0.8,-1.2,0.12,0,0,0,-0.5,0,0,0,-0.9,0,0,0,0,-1,0,0,-0.5,0,0,0,-1.5,-0.5,0,-1.5,-1.5,0,-3,-4,-1.5,0,-0.8,0,-0.5,0,-0.5,0,-1.5,-0.5,0,0,0];
var HI=[4.5,0.8,1.2,0.88,0.9,2.2,1.2,0.5,0.5,8,3,0.4,10,2,8,2,1.5,1.5,5,0.5,1,4,3,1.5,1.5,1.5,1.5,1.5,2,3,4,1.5,1.5,0.8,3,0.5,3,1.5,1.5,1.5,1.5,0.3,3,2];
function pv(p,i){var v=p&&p[i];if(typeof v!=="number"||!isFinite(v))v=DEF[i];return v;}
function clampParams(a){var b=new Array(N);for(var i=0;i<N;i++){var v=a&&a[i];if(typeof v!=="number"||!isFinite(v))v=DEF[i];b[i]=clampv(v,LO[i],HI[i]);}return b;}

function policy(obs,params,mem){
  if(!mem)mem={};
  var p=params;
  if(!p||typeof p.length!=="number")p=DEF;
  var t=+obs[19];if(!isFinite(t))t=0;

  if(!mem.calDone){
    if(mem.ct===undefined)mem.ct=0;
    var ct=mem.ct;
    if(ct===0)mem.q0=[obs[5],obs[7],obs[10],obs[12]];
    var outC;
    if(ct<3){
      outC=[0.05,0.05,0.05,0.05];
    }else if(ct===3){
      mem.qPos=[obs[5],obs[7],obs[10],obs[12]];
      outC=[-0.05,-0.05,-0.05,-0.05];
    }else if(ct<6){
      outC=[-0.05,-0.05,-0.05,-0.05];
    }else if(ct===6){
      mem.qNeg=[obs[5],obs[7],obs[10],obs[12]];
      var sg=[1,1,1,1];
      for(var j=0;j<4;j++){
        var dp=mem.qPos[j]-mem.q0[j];
        var dn=mem.qNeg[j]-mem.qPos[j];
        var sc=dp-dn;
        if(isFinite(sc)&&sc<-0.006)sg[j]=-1;else sg[j]=1;
      }
      mem.signs=sg;
      mem.calDone=true;
      mem.ct=ct+1;
      return [0,0,0,0];
    }else{
      outC=[0,0,0,0];
    }
    mem.ct=ct+1;
    return outC;
  }

  if(t<0.18)return [0,0,0,0];

  var theta=+obs[0],spin=+obs[1],vx=+obs[2],vy=+obs[3],height=+obs[4];
  var footA=+obs[9],footB=+obs[14];
  var h1=+obs[15],h2=+obs[16],h3=+obs[17],h4=+obs[18];
  if(!isFinite(theta))theta=0;
  if(!isFinite(spin))spin=0;
  if(!isFinite(vx))vx=0;
  if(!isFinite(vy))vy=0;
  if(!isFinite(height))height=0.8;
  if(!isFinite(footA))footA=0;
  if(!isFinite(footB))footB=0;
  if(!isFinite(h1))h1=0;
  if(!isFinite(h2))h2=0;
  if(!isFinite(h3))h3=0;
  if(!isFinite(h4))h4=0;

  var te=t-0.18;if(te<0)te=0;
  var endur=clampv((t-9.2)/2.0,0,1);
  var late=clampv((t-9.6)/3.2,0,1);
  var emg=Math.max(
    clampv((Math.abs(theta)-0.85)/0.45,0,1),
    clampv((0.46-height)/0.20,0,1),
    clampv((Math.abs(spin)-3.5)/2.5,0,1)
  );

  var freq=Math.max(0.05,pv(p,0));
  var phaseOff=pv(p,7);
  var d=clampv(pv(p,3),0.15,0.85);
  var h0=pv(p,1);
  var hA=pv(p,2);
  if(Math.abs(hA)<0.12)hA=(hA<0?-0.12:0.12);
  var vdes=pv(p,18)-pv(p,37)*endur;
  vdes-=0.10*late+0.20*emg;
  if(vdes<0.15)vdes=0.15;
  var strideGain=pv(p,35);
  if(Math.abs(strideGain)>1e-9){
    hA*=clampv(1+strideGain*clampv(vdes-vx,-2,2),0.4,1.8);
  }
  var hDamp=1-0.12*late-0.35*emg;
  if(hDamp<0.45)hDamp=0.45;
  hA*=hDamp;
  var kBase=-0.06-Math.max(0,pv(p,4));
  var kSw=Math.max(0,pv(p,5));
  var kSt=Math.max(0,pv(p,6));
  var legOff=pv(p,8);

  var rampTime=0.65;
  var ramp=clampv(te/rampTime,0,1);
  ramp=ramp*ramp*(3-2*ramp);

  var slope=0;
  if(isFinite(h1)&&isFinite(h2))slope=(h2-h1)*2;
  var lean=pv(p,11);
  lean=lean-pv(p,17)*clampv(vdes-vx,-2.5,2.5)-pv(p,25)*clampv(slope,-0.3,0.3);
  lean=clampv(lean,-0.9,0.7);

  var hh=Math.max(0,h1-0.03,(h2-0.05)*0.9,(h3-0.08)*0.7,(h4-0.12)*0.45);
  if(!isFinite(hh)||hh<0)hh=0;
  var hh4=Math.max(0,h4-0.12);
  var step=Math.max(0,h1-0.06,(h2-0.11)*0.9,(h3-0.18)*0.65,(h4-0.26)*0.4);
  if(!isFinite(step)||step<0)step=0;

  var balBase;
  var balScale=pv(p,23)*(1+pv(p,36)*endur);
  balScale*=(1+0.40*late+1.00*emg);
  balBase=clampv(pv(p,9)*(theta-lean)+pv(p,10)*spin,-2.5,2.5)*ramp;
  if(Math.abs(theta)>0.8||height<0.5)balBase*=1.8;
  balBase*=balScale;

  var p33=pv(p,33);
  var phaseBase;
  if(Math.abs(p33)>1e-7){
    if(!mem.phaseOn){mem.phase=0;mem.lastTe=0;mem.phaseOn=true;}
    var dte=te-mem.lastTe;
    if(!(dte>0))dte=0;
    if(dte>0.1)dte=0.1;
    var fAdj=freq*clampv(1+p33*clampv(vdes-vx,-2,2),0.5,1.8);
    mem.phase+=fAdj*dte;
    mem.lastTe=te;
    phaseBase=mem.phase;
  }else{
    phaseBase=freq*te;
  }

  var raw=[0,0,0,0];
  var signs=mem.signs||[1,1,1,1];
  if(!mem.prevH){mem.prevH=[null,null];mem.prevK=[null,null];}

  for(var i=0;i<2;i++){
    var off=(i===0)?0:legOff;
    var s=phaseBase+phaseOff+off;
    s=s-Math.floor(s);
    var x,hipTraj,kneeExtra,swingW;
    if(s<d){
      x=(d>1e-6)?s/d:0;
      hipTraj=Math.cos(Math.PI*x);
      kneeExtra=-kSt*Math.sin(Math.PI*x);
      swingW=0;
    }else{
      var den=1-d;
      if(den<1e-6)den=1e-6;
      x=(s-d)/den;
      hipTraj=-Math.cos(Math.PI*x);
      kneeExtra=-kSw*Math.sin(Math.PI*x);
      swingW=Math.sin(Math.PI*x);
    }
    var stanceW=1-swingW;
    var foot=(i===0)?footA:footB;

    var hipTarget=h0+hA*hipTraj;
    var kneeTarget=kBase+kneeExtra;

    hipTarget+=pv(p,19)*Math.sin(4*Math.PI*s+2*Math.PI*pv(p,20));
    hipTarget+=pv(p,16)*(vx-vdes)*(0.2+0.8*swingW);
    hipTarget+=pv(p,24)*hh*swingW;
    hipTarget+=pv(p,26)*theta*swingW+pv(p,27)*spin*swingW;
    hipTarget+=pv(p,39)*slope*swingW;

    kneeTarget-=pv(p,21)*hh*(0.25+0.75*swingW);
    kneeTarget-=pv(p,28)*swingW;
    kneeTarget+=pv(p,29)*vy*stanceW;
    kneeTarget+=pv(p,30)*(0.78-height)*stanceW;
    if(hh4>0.001&&swingW>0.02)kneeTarget-=pv(p,42)*hh4*swingW;

    if(step>0.001){
      var swStep=0.15+0.85*swingW;
      hipTarget+=0.16*step*swStep;
      kneeTarget-=(0.70+0.25*endur)*step*swStep;
    }

    if(swingW>0.05&&foot>0.5)kneeTarget-=pv(p,22)*swingW;
    if(foot>0.5&&swingW>0.1)hipTarget-=pv(p,31)*swingW;
    if(foot>0.5&&swingW>0.05)hipTarget-=pv(p,38)*swingW;
    if(step>0.015&&swingW>0.03&&foot>0.5){
      kneeTarget-=(0.35+1.1*step)*swingW;
      hipTarget-=0.10*swingW;
    }
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,32)*(x-0.3);
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,43)*(x-0.3);

    var cg=pv(p,34);
    if(cg>0&&swingW>0.02&&(hh>0.005||step>0.005)){
      var footDrop=0.38*Math.cos(hipTarget)+0.43*Math.cos(hipTarget+kneeTarget);
      var hipH=height-0.255*Math.cos(theta);
      var clear=hipH-footDrop;
      var want=pv(p,41)+0.95*hh+0.40*step;
      if(want<0.01)want=0.01;
      if(clear<want){
        var add=(want-clear)*cg;
        if(add>0.9)add=0.9;
        kneeTarget-=add;
        hipTarget-=pv(p,40)*add;
      }
    }

    hipTarget=clampv(hipTarget,-0.88,1.18);
    kneeTarget=clampv(kneeTarget,-1.65,-0.055);

    var hipT=ramp*hipTarget+(1-ramp)*0.0;
    var kneeT=ramp*kneeTarget+(1-ramp)*(-0.06);

    var qHip=(i===0)?+obs[5]:+obs[10];
    var qdHip=(i===0)?+obs[6]:+obs[11];
    var qKnee=(i===0)?+obs[7]:+obs[12];
    var qdKnee=(i===0)?+obs[8]:+obs[13];
    if(!isFinite(qHip))qHip=0;
    if(!isFinite(qdHip))qdHip=0;
    if(!isFinite(qKnee))qKnee=-0.06;
    if(!isFinite(qdKnee))qdKnee=0;

    var prevH=mem.prevH[i],prevK=mem.prevK[i];
    var velH=0,velK=0;
    if(prevH!==null&&prevH!==undefined)velH=(hipT-prevH)*60;
    if(prevK!==null&&prevK!==undefined)velK=(kneeT-prevK)*60;
    if(!isFinite(velH))velH=0;
    if(!isFinite(velK))velK=0;
    velH=clampv(velH,-25,25);
    velK=clampv(velK,-25,25);
    mem.prevH[i]=hipT;
    mem.prevK[i]=kneeT;

    var hipKp=Math.max(0,pv(p,12));
    var hipKd=Math.max(0,pv(p,13));
    var kneeKp=Math.max(0,pv(p,14));
    var kneeKd=Math.max(0,pv(p,15));

    var tauH=hipKp*(hipT-qHip)+hipKd*(velH-qdHip);
    var tauK=kneeKp*(kneeTarget-qKnee)+kneeKd*(velK-qdKnee);

    var footW=(foot>0.5)?1:0.2;
    tauH+=balBase*footW;

    raw[2*i]=clampv(tauH,-1,1);
    raw[2*i+1]=clampv(tauK,-1,1);
  }

  return [signs[0]*raw[0],signs[1]*raw[1],signs[2]*raw[2],signs[3]*raw[3]];
}

function learn(lab){
  var n=N;
  var cache={};
  var seenItems=[];
  var best=null;

  function keyOf(x){
    var s="";
    for(var i=0;i<n;i++)s+=Math.round(x[i]*50000)+",";
    return s;
  }

  function evaluate(x){
    x=clampParams(x);
    var key=keyOf(x);
    if(cache[key])return cache[key];
    if(lab.trialsLeft()<=0){
      return {x:x.slice(),score:-1e9,distance:0,outcome:"none",time:0,energy:0,stable:false};
    }
    var res;
    try{
      res=lab.trial(x.slice());
    }catch(e){
      res={distance:0,outcome:"error",time:0,energy:0};
    }
    if(!res)res={};
    var dist=Number(res.distance);
    if(!isFinite(dist)||dist<0)dist=Math.max(0,isFinite(dist)?dist:0);
    var outcome=String(res.outcome||"");
    var time=Number(res.time);
    if(!isFinite(time)||time<0)time=0;
    if(time>10)time=10;
    var energy=Number(res.energy);
    if(!isFinite(energy))energy=0;

    var score;
    if(outcome==="invalid"||outcome==="error"){
      score=-1000000+Math.max(0,dist);
    }else{
      score=dist+0.04*time;
      if(outcome==="finished")score+=0.6;
      if(time>=9.95)score+=0.6;
      if(outcome==="fell")score-=Math.max(0,10-time)*0.18;
      if(time>9.7&&dist>0.1)score+=0.1;
      if(!isFinite(score))score=-1e9;
    }
    var stable=(time>=9.70&&outcome!=="fell"&&outcome!=="invalid"&&outcome!=="error");
    var item={
      x:x.slice(),score:score,distance:dist,outcome:outcome,time:time,
      energy:energy,stable:stable
    };
    cache[key]=item;
    seenItems.push(item);
    if(!best||item.score>best.score)best=item;
    return item;
  }

  function mk(base,o){
    var x=(base||DEF).slice();
    for(var k in o){
      if(o.hasOwnProperty(k)){
        var idx=+k;
        if(idx>=0&&idx<n)x[idx]=o[k];
      }
    }
    return clampParams(x);
  }

  function gauss(){
    var u=Math.random();
    if(u<1e-12)u=1e-12;
    var v=Math.random();
    return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  }

  function sample(mean,sig,mask){
    var x=new Array(n);
    for(var j=0;j<n;j++){
      if(sig[j]>1e-12&&(!mask||mask[j]))x[j]=mean[j]+sig[j]*gauss();
      else x[j]=mean[j];
    }
    if(Math.random()<0.022){
      var inds=[];
      for(var j2=0;j2<n;j2++){
        if(!mask||mask[j2])inds.push(j2);
      }
      if(inds.length){
        var jj=inds[Math.floor(Math.random()*inds.length)];
        x[jj]=LO[jj]+Math.random()*(HI[jj]-LO[jj]);
      }
    }
    return clampParams(x);
  }

  function runCEM(start,frac,maxTrials,lambda,mu,genLimit,mask){
    if(lab.trialsLeft()<=0)return null;
    var targetLeft=lab.trialsLeft()-maxTrials;
    if(targetLeft<0)targetLeft=0;
    var mean=clampParams(start.slice());
    var sig=new Array(n);
    for(var j=0;j<n;j++){
      var range=HI[j]-LO[j];
      sig[j]=Math.max(range*frac,range*0.001);
      if(mask&&!mask[j])sig[j]=0;
    }
    var localBest=evaluate(mean);
    var noImp=0;

    for(var gen=0;gen<genLimit&&lab.trialsLeft()>targetLeft;gen++){
      var pop=[];
      if(lab.trialsLeft()>targetLeft)pop.push(evaluate(mean));
      for(var k=1;k<lambda&&lab.trialsLeft()>targetLeft;k++){
        pop.push(evaluate(sample(mean,sig,mask)));
      }
      if(!pop.length)break;
      pop.sort(function(a,b){return b.score-a.score;});
      var improved=pop[0].score>localBest.score+1e-9;
      if(pop[0].score>localBest.score+1e-9)localBest=pop[0];

      var e=Math.min(mu,pop.length);
      var newMean=new Array(n);
      var varArr=new Array(n);
      var weights=new Array(e);
      for(var j1=0;j1<n;j1++){newMean[j1]=0;varArr[j1]=0;}
      var wsum=0;
      for(var q=0;q<e;q++){
        var w=Math.exp(-0.5*q);
        weights[q]=w;
        wsum+=w;
        var xx=pop[q].x;
        for(var j2=0;j2<n;j2++)newMean[j2]+=w*xx[j2];
      }
      for(var j3=0;j3<n;j3++)newMean[j3]/=wsum;
