  function coordinateSearch(start,maxTrials,stepFrac,maxSweeps,mask){
    if(lab.trialsLeft()<=0)return null;
    var targetLeft=lab.trialsLeft()-maxTrials;
    if(targetLeft<0)targetLeft=0;
    var x=clampParams(start.slice());
    var cur=evaluate(x);
    var step=new Array(n);
    for(var j=0;j<n;j++){
      var rr=HI[j]-LO[j];
      step[j]=Math.max(rr*stepFrac,rr*0.001);
      if(mask&&!mask[j])step[j]=0;
    }
    var sweeps=0;
    while(lab.trialsLeft()>targetLeft&&sweeps<maxSweeps){
      var inds=[];
      for(var j2=0;j2<n;j2++)if(step[j2]>0)inds.push(j2);
      for(var a=inds.length-1;a>0;a--){
        var b=Math.floor(Math.random()*(a+1));
        var tmp=inds[a];inds[a]=inds[b];inds[b]=tmp;
      }
      var improvedAny=false;
      for(var idx=0;idx<inds.length&&lab.trialsLeft()>targetLeft;idx++){
        var jj=inds[idx];
        var bestIt=null,bestX=null;
        var signs=(Math.random()<0.5)?[1,-1]:[-1,1];
        for(var ss=0;ss<2&&lab.trialsLeft()>targetLeft;ss++){
          var y=x.slice();
          var nv=x[jj]+signs[ss]*step[jj];
          if(nv<LO[jj])nv=LO[jj];
          if(nv>HI[jj])nv=HI[jj];
          if(Math.abs(nv-x[jj])<1e-12)continue;
          y[jj]=nv;
          y=clampParams(y);
          var it=evaluate(y);
          if(!bestIt||it.score>bestIt.score){bestIt=it;bestX=y;}
        }
        if(bestIt&&bestIt.score>cur.score+1e-9){
          x=clampParams(bestX);
          cur=bestIt;
          improvedAny=true;
          var rjj=HI[jj]-LO[jj];
          step[jj]=Math.min(rjj*0.5,step[jj]*1.15);
        }else{
          step[jj]*=0.8;
        }
      }
      if(!improvedAny){
        for(var j3=0;j3<n;j3++)if(step[j3]>0)step[j3]*=0.7;
        var maxRatio=0;
        for(var j4=0;j4<n;j4++){
          var r5=HI[j4]-LO[j4];
          if(r5>0)maxRatio=Math.max(maxRatio,step[j4]/r5);
        }
        if(maxRatio<0.0025)break;
      }
      sweeps++;
    }
    return cur;
  }

  function getTop(count,stableOnly){
    var arr=seenItems.slice();
    if(stableOnly){
