    velH=clampv(velH,-25,25);
    velK=clampv(velK,-25,25);
    mem.prevH[i]=hipT;
    mem.prevK[i]=kneeT;

    var damp=1+0.30*endur+0.20*late+0.45*emg;
    var hipKp=Math.max(0,pv(p,12))*(1-0.04*endur-0.06*emg);
    var hipKd=(Math.max(0,pv(p,13))+0.025*endur+0.010*late)*damp;
