    }
    if(!res)res={};
    var dist=Number(res.distance);
    if(!isFinite(dist)||dist<0)dist=0;
    var outcome=String(res.outcome||"");
    var time=Number(res.time);
    if(!isFinite(time)||time<0)time=0;
    if(time>10)time=10;
    var energy=Number(res.energy);
    if(!isFinite(energy))energy=0;

    var stable=(outcome!=="fell"&&outcome!=="invalid"&&outcome!=="error"&&time>=9.75);
    var finished=(outcome==="finished"||time>=9.95);
    var score;
    if(outcome==="invalid"||outcome==="error"){
      score=-1000000+dist;
    }else{
      score=dist+(stable?8.0:0)+(finished?1.0:0);
      if(!stable)score-=2.0*(10-time);
      if(outcome==="fell")score-=3.0;
      if(time<0.5&&dist<0.1)score-=5.0;
      if(outcome==="finished")score+=0.5;
    }
    var item={
      x:x.slice(),score:score,distance:dist,outcome:outcome,time:time,
      energy:energy,stable:stable,finished:finished
