  function gauss(){
    var u=Math.random();
    if(u<1e-12)u=1e-12;
    var v=Math.random();
    return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  }

  var maskSearch=new Array(n);
  for(var mi=0;mi<n;mi++)maskSearch[mi]=true;
  maskSearch[44]=false;
  var frozen=[21,22,24,25,28,32,34,38,39,40,41,42,43];
  for(var fi=0;fi<frozen.length;fi++)maskSearch[frozen[fi]]=false;

  function perturb(base,sigma){
    var x=clampParams(base);
    for(var j=0;j<n;j++){
      if(maskSearch[j]&&Math.random()<0.35)x[j]+=gauss()*(HI[j]-LO[j])*sigma;
    }
    return fixParams(x);
  }

  function sample(mean,sig,mask){
    var x=new Array(n);
    for(var j=0;j<n;j++){
      if(mask[j]&&sig[j]>1e-12)x[j]=mean[j]+sig[j]*gauss();
      else x[j]=mean[j];
    }
