var HI=HIB.concat([1]);

function fixParams(a){
  var b=new Array(N);
  for(var i=0;i<N;i++){
    var v=a&&a[i];
    if(typeof v!=="number"||!isFinite(v))v=0;
    b[i]=clampv(v,LO[i],HI[i]);
  }
  if(b[12]<1.0)b[12]=1.0;
  if(b[13]<0.03)b[13]=0.03;
  if(b[14]<0.80)b[14]=0.80;
  if(b[15]<0.15)b[15]=0.15;
  if(Math.abs(b[2])<0.12)b[2]=(b[2]<0?-0.12:0.12);
  if(b[3]<0.15)b[3]=0.15;
  if(b[3]>0.85)b[3]=0.85;
  if(b[8]<0.25)b[8]=0.25;
  if(b[8]>0.75)b[8]=0.75;
  if(b[21]<0.80)b[21]=0.80;
  if(b[24]<0.00)b[24]=0.00;
  if(b[34]<0.35)b[34]=0.35;
  if(b[40]<0.10)b[40]=0.10;
  if(b[41]<0.012)b[41]=0.012;
  if(b[42]<0.20)b[42]=0.20;
  if(b[44]<0.60)b[44]=0.60;
  if(b[36]<0.20)b[36]=0.20;
  if(b[37]<0.08)b[37]=0.08;
  if(b[30]<-0.20)b[30]=-0.20;
  if(b[30]>1.20)b[30]=1.20;
  if(Math.abs(b[23])<0.35)b[23]=(b[23]>=0?0.35:-0.35);
  if(b[23]>3)b[23]=3;
  if(b[23]<-3)b[23]=-3;
  if(b[9]<0.05)b[9]=0.05;
  return b;
}

var B3D=[2.2999247408921217,0.17721817743623847,-0.42487600224766353,0.3429806424815196,0.24492225153194958,0.5127148876638689,0.28228862162317025,-0.18021453536159127,0.49843190044339386,0.23653925166068884,0.044175465901872185,-0.25948081693082214,3.065118767235171,0.11253754300706421,2.0554604161877794,0.5679969385763781,-0.17055761445824785,0.14829924127014263,1.728443831897868,-0.10085997936315917,0.7992571401752417,1.395956411717889,0.6214954912641022,-1.1730759822339734,0.29051607795305556,0.37364907537697956,0,0,0,0,0,0,0,0,0.9,0.8,0.6,0.12,0,0.15,0.15,0.015,0.25,0,0.85];
var DEF=fixParams(B3D.slice());

function pv(p,i){var v=p&&p[i];if(typeof v!=="number"||!isFinite(v))v=DEF[i];return v;}

function policy(obs,params,mem){
  if(!mem)mem={};
  var p=params;
  if(!p||typeof p.length!=="number")p=DEF;
  var t=+obs[19];if(!isFinite(t))t=0;

  if(!mem.calDone){
    if(mem.ct===undefined)mem.ct=0;
    var ct=mem.ct;
    if(ct===0)mem.q0=[obs[5],obs[7],obs[10],obs[12]];
    var outC;
    if(ct<3){
      outC=[0.05,0.05,0.05,0.05];
    }else if(ct===3){
      mem.qPos=[obs[5],obs[7],obs[10],obs[12]];
      outC=[-0.05,-0.05,-0.05,-0.05];
    }else if(ct<6){
      outC=[-0.05,-0.05,-0.05,-0.05];
    }else if(ct===6){
      mem.qNeg=[obs[5],obs[7],obs[10],obs[12]];
      var sg=[1,1,1,1];
      for(var j=0;j<4;j++){
        var dp=mem.qPos[j]-mem.q0[j];
        var dn=mem.qNeg[j]-mem.qPos[j];
        var sc=dp-dn;
        if(isFinite(sc)&&sc<-0.006)sg[j]=-1;else sg[j]=1;
      }
      mem.signs=sg;
      mem.calDone=true;
      mem.ct=ct+1;
      return [0,0,0,0];
    }else{
      outC=[0,0,0,0];
    }
    mem.ct=ct+1;
    return outC;
  }

  if(t<0.18)return [0,0,0,0];

  var theta=+obs[0],spin=+obs[1],vx=+obs[2],vy=+obs[3],height=+obs[4];
  var footA=+obs[9],footB=+obs[14];
  var h1=+obs[15],h2=+obs[16],h3=+obs[17],h4=+obs[18];
  if(!isFinite(theta))theta=0;
  if(!isFinite(spin))spin=0;
  if(!isFinite(vx))vx=0;
  if(!isFinite(vy))vy=0;
  if(!isFinite(height))height=0.8;
  if(!isFinite(footA))footA=0;
  if(!isFinite(footB))footB=0;
  if(!isFinite(h1))h1=0;
  if(!isFinite(h2))h2=0;
  if(!isFinite(h3))h3=0;
  if(!isFinite(h4))h4=0;

  var safe=clampv(pv(p,44),0,1);
  var te=t-0.18;if(te<0)te=0;
  var endur=clampv((t-10.0)/3.5,0,1);
  var late=clampv((t-14.0)/4.0,0,1);

  var slope=0;
  if(isFinite(h1)&&isFinite(h2))slope=(h2-h1)*2;
  var hh=Math.max(0,h1-0.03,(h2-0.05)*0.9,(h3-0.08)*0.7,(h4-0.12)*0.45);
  if(!isFinite(hh)||hh<0)hh=0;
  var hh4=Math.max(0,h4-0.12);
  var step=Math.max(0,h1-0.08,(h2-0.14)*0.85,(h3-0.20)*0.65,(h4-0.24)*0.45);
  if(!isFinite(step)||step<0)step=0;
  var drop=Math.max(0,-h1-0.03,-h2*0.8-0.03,-h3*0.6-0.03,-h4*0.4-0.02);
  if(!isFinite(drop)||drop<0)drop=0;

  var emg=Math.max(
    clampv((Math.abs(theta)-0.62)/0.45,0,1),
    clampv((0.55-height)/0.20,0,1),
    clampv((Math.abs(spin)-2.5)/2.2,0,1)
  );
  var danger=Math.max(
    clampv((Math.abs(theta)-0.40)/0.35,0,1),
    clampv((0.60-height)/0.16,0,1),
    clampv((Math.abs(spin)-1.8)/2.0,0,1)
  );
  var enable=clampv((t-8.8)/2.5,0,1);
  var lowHeight=clampv((0.54-height)/0.15,0,1);
  var risk0=Math.max(danger*enable,lowHeight);
  if(typeof mem.risk!=="number")mem.risk=0;
  mem.risk=Math.max(risk0,mem.risk*0.985);
  var timeRisk=clampv((t-12.5)/6.5,0,1)*(0.15+0.35*safe);
  var rescueW=clampv(Math.max(mem.risk,timeRisk),0,1);
  var slowW=rescueW;

  var freq=Math.max(0.05,pv(p,0)*(1-0.015*endur-0.020*late));
  var phaseOff=pv(p,7);
  var d=clampv(pv(p,3),0.15,0.85);
  var h0=pv(p,1);
  var hA=pv(p,2);
  if(Math.abs(hA)<0.12)hA=(hA<0?-0.12:0.12);
  var vdes=pv(p,18)-pv(p,37)*endur;
  vdes-=0.10*endur+0.10*late+1.0*slowW;
  if(vdes<0.15)vdes=0.15;
  var strideGain=pv(p,35);
  if(Math.abs(strideGain)>1e-9){
    hA*=clampv(1+strideGain*clampv(vdes-vx,-2,2),0.4,1.8);
  }
  hA*=clampv(1-0.55*slowW-0.05*endur,0.25,1.0);
  if(Math.abs(hA)<0.04)hA=(hA<0?-0.04:0.04);

  var kBase=-0.06-Math.max(0,pv(p,4));
  var kSw=Math.max(0,pv(p,5));
  var kSt=Math.max(0,pv(p,6));
  var legOff=pv(p,8);

  var ramp=clampv(te/0.65,0,1);
  ramp=ramp*ramp*(3-2*ramp);

  var lean=pv(p,11)-pv(p,17)*clampv(vdes-vx,-2.5,2.5)-pv(p,25)*clampv(slope,-0.3,0.3);
  lean=clampv(lean,-0.9,0.7);
  lean*=(1-0.15*endur);

  var balScale=pv(p,23)*(1+pv(p,36)*endur);
  balScale*=(1+0.35*endur+0.20*late+0.70*emg+0.50*safe*emg+1.10*slowW);
  var balBase=clampv(pv(p,9)*(theta-lean)+pv(p,10)*spin,-2.5,2.5)*ramp;
  if(Math.abs(theta)>0.62||height<0.55)balBase*=1.8;
  balBase*=balScale;

  var p33=pv(p,33);
  var phaseBase;
  if(Math.abs(p33)>1e-7){
    if(!mem.phaseOn){mem.phase=0;mem.lastTe=0;mem.phaseOn=true;}
    var dte=te-mem.lastTe;
    if(!(dte>0))dte=0;
    if(dte>0.1)dte=0.1;
    var fAdj=freq*clampv(1+p33*clampv(vdes-vx,-2,2),0.5,1.8);
    mem.phase+=fAdj*dte;
    mem.lastTe=te;
    phaseBase=mem.phase;
  }else{
    phaseBase=freq*te;
  }

  var raw=[0,0,0,0];
  var signs=mem.signs||[1,1,1,1];
  if(!mem.prevH){mem.prevH=[null,null];mem.prevK=[null,null];}

  for(var i=0;i<2;i++){
    var off=(i===0)?0:legOff;
    var s=phaseBase+phaseOff+off;
    s=s-Math.floor(s);
    var x,hipTraj,kneeExtra,swingW;
    if(s<d){
      x=(d>1e-6)?s/d:0;
      hipTraj=Math.cos(Math.PI*x);
      kneeExtra=-kSt*Math.sin(Math.PI*x);
      swingW=0;
    }else{
      var den=1-d;
      if(den<1e-6)den=1e-6;
      x=(s-d)/den;
      hipTraj=-Math.cos(Math.PI*x);
      kneeExtra=-kSw*Math.sin(Math.PI*x);
      swingW=Math.sin(Math.PI*x);
    }
    var stanceW=1-swingW;
    var foot=(i===0)?footA:footB;

    var hipTarget=h0+hA*hipTraj;
    var kneeTarget=kBase+kneeExtra;

    hipTarget+=pv(p,19)*Math.sin(4*Math.PI*s+2*Math.PI*pv(p,20));
    hipTarget+=pv(p,16)*(vx-vdes)*(0.2+0.8*swingW);
    hipTarget+=pv(p,24)*hh*swingW;
    hipTarget+=pv(p,26)*theta*swingW+pv(p,27)*spin*swingW;
    hipTarget+=pv(p,39)*slope*swingW;

    kneeTarget-=pv(p,21)*hh*(0.25+0.75*swingW);
    kneeTarget-=pv(p,28)*swingW;
    kneeTarget+=pv(p,29)*vy*stanceW;
    kneeTarget+=pv(p,30)*(0.78-height)*stanceW;
    if(hh4>0.001&&swingW>0.02)kneeTarget-=pv(p,42)*hh4*swingW;

    if(drop>0.005){
      kneeTarget+=(0.08+0.10*safe)*drop*(0.3+0.7*swingW);
      if(swingW>0.05)hipTarget+=0.03*drop*swingW;
    }

    var stepUse=step;
    if(stepUse>0.0025){
      var swf=0.20+0.80*swingW;
      hipTarget-=(0.30*stepUse)*swf;
      kneeTarget-=(0.85*stepUse)*(0.30+0.70*swingW);
    }

    if(swingW>0.035&&(Math.abs(theta)>0.18||Math.abs(spin)>1.2||emg>0.1)){
      hipTarget+=(0.12*theta+0.022*spin)*swingW*(1+0.7*emg+0.5*safe);
    }

    if(swingW>0.05&&foot>0.5){
      kneeTarget-=(0.35+0.45*clampv(step*4,0,1)+0.15*endur+0.15*safe)*swingW;
      hipTarget-=0.08*swingW;
    }
    if(swingW>0.05&&foot>0.5)kneeTarget-=pv(p,22)*swingW;
    if(foot>0.5&&swingW>0.1)hipTarget-=pv(p,31)*swingW;
    if(foot>0.5&&swingW>0.05)hipTarget-=pv(p,38)*swingW;
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,32)*(x-0.3);
    if(s<d&&foot<0.5&&x>0.3)kneeTarget+=pv(p,43)*(x-0.3);

    var needClear=(step>0.020)||(safe>0.5&&(hh>0.006||step>0.003)&&swingW>0.02);
    if(needClear&&swingW>0.02&&(hh>0.002||step>0.002)){
      var cg=pv(p,34);
      if(cg<0.35)cg=0.35;
      var footDrop=0.38*Math.cos(hipTarget)+0.43*Math.cos(hipTarget+kneeTarget);
      var hipH=height-0.255*Math.cos(theta);
      var want=pv(p,41)+0.95*hh+0.55*step+0.05*emg-0.20*drop;
      if(want<0.012)want=0.012;
      var clear=hipH-footDrop;
      if(clear<want){
        var add=(want-clear)*cg;
        if(add>0.95)add=0.95;
        kneeTarget-=add;
        var hg=pv(p,40);
        if(hg<0.10)hg=0.10;
        hipTarget-=hg*add;
      }
    }

    var blend=clampv(rescueW*0.85,0,0.85);
    if(blend>0){
      var standHip=h0*0.60;
      var standKnee=kBase;
      hipTarget=(1-blend)*hipTarget+blend*standHip;
      kneeTarget=(1-blend)*kneeTarget+blend*standKnee;
    }

    hipTarget=clampv(hipTarget,-0.88,1.18);
    kneeTarget=clampv(kneeTarget,-1.65,-0.055);

    var hipT=ramp*hipTarget+(1-ramp)*0.0;
    var kneeT=ramp*kneeTarget+(1-ramp)*(-0.06);

    var qHip=(i===0)?+obs[5]:+obs[10];
    var qdHip=(i===0)?+obs[6]:+obs[11];
    var qKnee=(i===0)?+obs[7]:+obs[12];
    var qdKnee=(i===0)?+obs[8]:+obs[13];
    if(!isFinite(qHip))qHip=0;
    if(!isFinite(qdHip))qdHip=0;
    if(!isFinite(qKnee))qKnee=-0.06;
    if(!isFinite(qdKnee))qdKnee=0;

    var prevH=mem.prevH[i],prevK=mem.prevK[i];
    var velH=0,velK=0;
    if(prevH!==null&&prevH!==undefined)velH=(hipT-prevH)*60;
    if(prevK!==null&&prevK!==undefined)velK=(kneeT-prevK)*60;
    if(!isFinite(velH))velH=0;
    if(!isFinite(velK))velK=0;
    velH=clampv(velH,-25,25);
    velK=clampv(velK,-25,25);
    mem.prevH[i]=hipT;
    mem.prevK[i]=kneeT;

    var damp=1+0.25*endur+0.18*late+0.35*emg+0.25*safe*emg+0.80*rescueW;
    var hipKp=Math.max(0,pv(p,12))*(1-0.03*endur)*(1+0.45*rescueW);
    var hipKd=(Math.max(0,pv(p,13))+0.020*endur+0.060*rescueW)*damp;
    var kneeKp=Math.max(0,pv(p,14))*(1-0.03*endur)*(1+0.45*rescueW);
    var kneeKd=(Math.max(0,pv(p,15))+0.020*endur+0.060*rescueW)*damp;

    var tauH=hipKp*(hipT-qHip)+hipKd*(velH-qdHip);
    var tauK=kneeKp*(kneeTarget-qKnee)+kneeKd*(velK-qdKnee);

    var footW=(foot>0.5)?1:0.2;
    tauH+=balBase*footW;

    raw[2*i]=clampv(tauH,-1,1);
    raw[2*i+1]=clampv(tauK,-1,1);
  }

  return [signs[0]*raw[0],signs[1]*raw[1],signs[2]*raw[2],signs[3]*raw[3]];
}

function learn(lab){
  var n=N;
  var cache={};
  var seenItems=[];
  var best=null;
  var bestStable=null;

  function keyOf(x){
    var s="";
    for(var i=0;i<n;i++)s+=Math.round(x[i]*100000)+",";
    return s;
  }

  function evaluate(x){
    x=fixParams(x);
    var key=keyOf(x);
    if(cache[key])return cache[key];
    if(lab.trialsLeft()<=0){
      return {x:x.slice(),score:-1e9,distance:0,outcome:"none",time:0,energy:0,stable:false,finished:false};
    }
    var res;
    try{
      res=lab.trial(x.slice());
    }catch(e){
      res={distance:0,outcome:"error",time:0,energy:0};
    }
    if(!res)res={};
    var dist=Number(res.distance);
    if(!isFinite(dist)||dist<0)dist=0;
    var outcome=String(res.outcome||"");
    var time=Number(res.time);
    if(!isFinite(time)||time<0)time=0;
    if(time>10)time=10;
    var energy=Number(res.energy);
    if(!isFinite(energy))energy=0;
    var bad=(outcome==="fell"||outcome==="invalid"||outcome==="error");
    var finished=(outcome==="finished");
    var stable=(!bad&&(finished||time>=9.65));
    var score;
    if(outcome==="invalid"||outcome==="error"){
      score=-1000000+dist;
    }else{
      score=dist+0.40*time;
      if(stable)score+=8.0;
      else score-=2.5*(10-time);
      if(outcome==="fell")score-=1.5;
      score+=0.10*x[44]+0.05*x[36]+0.05*x[37];
    }
    var item={x:x.slice(),score:score,distance:dist,outcome:outcome,time:time,energy:energy,stable:stable,finished:finished};
    cache[key]=item;
    seenItems.push(item);
    if(!best||item.score>best.score)best=item;
    if(item.stable&&(!bestStable||item.score>bestStable.score))bestStable=item;
    return item;
  }

  function addSeed(arr){
    var it=evaluate(fixParams(arr));
    return it;
  }

  function gauss(){
    var u=Math.random();
    if(u<1e-12)u=1e-12;
    var v=Math.random();
    return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  }

  function perturb(base,sigma){
    var x=fixParams(base.slice());
    for(var j=0;j<n;j++){
      if(Math.random()<0.35)x[j]+=gauss()*(HI[j]-LO[j])*sigma;
    }
    return fixParams(x);
  }

  function runES(start,maxTrials,frac,lambda,mu,mask){
    if(!start||lab.trialsLeft()<=0)return null;
    var target=lab.trialsLeft()-maxTrials;
    if(target<0)target=0;
    var mean=fixParams(start.slice());
    var sig=new Array(n);
    for(var j=0;j<n;j++){
      var rr=HI[j]-LO[j];
      sig[j]=mask[j]?Math.max(rr*frac,rr*0.001):0;
    }
    var localBest=evaluate(mean);
    var noImp=0;
    for(var gen=0;gen<200&&lab.trialsLeft()>target;gen++){
      var pop=[];
      if(lab.trialsLeft()>target)pop.push(evaluate(mean));
      for(var k=1;k<lambda&&lab.trialsLeft()>target;k++){
        var x=new Array(n);
        for(var j2=0;j2<n;j2++){
          if(sig[j2]>1e-12)x[j2]=mean[j2]+sig[j2]*gauss();
          else x[j2]=mean[j2];
        }
        if(Math.random()<0.030){
          var jj=Math.floor(Math.random()*n);
          if(mask[jj])x[jj]=LO[jj]+Math.random()*(HI[jj]-LO[jj]);
        }
        x=fixParams(x);
        pop.push(evaluate(x));
      }
      if(!pop.length)break;
      pop.sort(function(a,b){return b.score-a.score;});
      if(pop[0].score>localBest.score+1e-9){localBest=pop[0];noImp=0;}
      else noImp++;

      var e=Math.min(mu,pop.length);
      var newMean=new Array(n);
      var varArr=new Array(n);
      var weights=new Array(e);
      var wsum=0;
      for(var j3=0;j3<n;j3++){newMean[j3]=0;varArr[j3]=0;}
      for(var q=0;q<e;q++){
        var w=Math.exp(-0.5*q);
        weights[q]=w;
        wsum+=w;
        var xx=pop[q].x;
        for(var j4=0;j4<n;j4++)newMean[j4]+=w*xx[j4];
      }
      for(var j5=0;j5<n;j5++)newMean[j5]/=wsum;
      for(var q2=0;q2<e;q2++){
        var w2=weights[q2];
        var xq=pop[q2].x;
        for(var j6=0;j6<n;j6++){
          var dd=xq[j6]-newMean[j6];
          varArr[j6]+=w2*dd*dd;
        }
      }
      for(var j7=0;j7<n;j7++){
        if(!mask[j7]){
          mean[j7]=mean[j7];
          sig[j7]=0;
          continue;
        }
        var range=HI[j7]-LO[j7];
        var vv=Math.sqrt(Math.max(0,varArr[j7]/wsum));
        var ns=0.65*vv+0.35*sig[j7];
        var minS=Math.max(range*0.0015,0.0001);
        var maxS=Math.max(minS,range*0.52);
        sig[j7]=clampv(ns,minS,maxS);
        mean[j7]=clampv(0.45*newMean[j7]+0.55*pop[0].x[j7],LO[j7],HI[j7]);
      }
      mean=fixParams(mean);
      if(noImp>=5){
        mean=fixParams(localBest.x.slice());
        for(var j8=0;j8<n;j8++){
          if(mask[j8]){
            var r8=HI[j8]-LO[j8];
            sig[j8]=Math.min(r8*0.50,Math.max(r8*0.002,sig[j8]*1.40));
          }
        }
        noImp=0;
      }
    }
    return localBest;
  }

  function coord(start,maxTrials,stepFrac,maxSweeps,mask){
    if(!start||lab.trialsLeft()<=0)return null;
    var target=lab.trialsLeft()-maxTrials;
    if(target<0)target=0;
    var x=fixParams(start.slice());
    var cur=evaluate(x);
    var step=new Array(n);
    for(var j=0;j<n;j++){
      var rr=HI[j]-LO[j];
      step[j]=mask[j]?Math.max(rr*stepFrac,rr*0.001):0;
    }
    var sweeps=0;
    while(lab.trialsLeft()>target&&sweeps<maxSweeps){
      var inds=[];
