  const lo = [0.5, -0.5, -0.9, -1.4, 0, -Math.PI, -Math.PI, 1, 0, -2, -0.3];
  const hi = [3.5, 0.8, 0.9, -0.2, 1.2, Math.PI, Math.PI, 12, 0.6, 2, 0.3];
  const D = keys.length;

  const t0 = (typeof Date !== 'undefined') ? Date.now() : 0;
  const timeUp = () => (typeof Date !== 'undefined') && (Date.now() - t0 > 150000);

  const toP = x => {
    const o = {};
    for (let i = 0; i < D; i++) o[keys[i]] = lo[i] + clamp01(x[i]) * (hi[i] - lo[i]);
    return o;
  };

  let bestF = -Infinity, bestX = null;

  const budgetLeft = () => {
    try { return lab.trialsLeft() > 0 && !timeUp(); } catch (e) { return false; }
  };

