    if (!budgetLeft()) return null;
    let d = -1;
    try {
      const r = lab.trial(toP(x));
      if (r && typeof r.distance === 'number' && isFinite(r.distance)) d = r.distance;
    } catch (e) {
      d = -1;
    }
    if (d > bestF) { bestF = d; bestX = x.slice(); }
    return d;
  };

  const gauss = () => {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

