  // Random exploration
  const nRand = 40;
  for (let i = 0; i < nRand && budgetLeft(); i++) {
    const x = [];
    for (let j = 0; j < D; j++) x.push(Math.random());
    const d = evalX(x);
    if (d === null) break;
    pop.push({ x: x, f: d });
