  pop.sort((a, b) => b.f - a.f);
  const starts = pop.slice(0, 3);

  // (1+1)-ES with 1/5 success rule from each start, sharing the remaining budget
  for (let si = 0; si < starts.length && budgetLeft(); si++) {
    let cur = starts[si].x.slice();
    let fc = starts[si].f;
    let sigma = 0.15;
    let succ = 0, tries = 0;
    const share = Math.floor(lab.trialsLeft() / (starts.length - si));
    const stopAt = Math.max(0, share - 1);
    let used = 0;
    while (budgetLeft() && used < stopAt) {
      const cand = cur.map(v => clamp01(v + sigma * gauss()));
      const fcand = evalX(cand);
      if (fcand === null) break;
      used++;
      tries++;
      if (fcand >= fc) {
        cur = cand;
        fc = fcand;
        succ++;
      }
      if (tries >= 10) {
        const rate = succ / tries;
        sigma = rate > 0.2 ? sigma * 1.3 : sigma * 0.8;
        sigma = Math.min(0.3, Math.max(0.01, sigma));
        succ = 0; tries = 0;
