  const hip0 = num(P.hip0, 0), hipAmp = num(P.hipAmp, 0.5), hip2 = num(P.hip2, 0);
  const knee0 = num(P.knee0, -0.7), kneeAmp = num(P.kneeAmp, 0.4);
  const kr = clamp(num(P.kr, 0.5), 0, 1);
  const phK = num(P.phK, 0), phB = num(P.phB, Math.PI);
  const kp = num(P.kp, 8), kd = num(P.kd, 0.3);
  const bal = num(P.bal, 0), balSpin = num(P.balSpin, 0), balV = num(P.balV, 0);
  const kneeBal = num(P.kneeBal, 0), kh = num(P.kh, 0.35);
  const bi = num(P.bi, 0);

  const M = (mem && typeof mem === 'object') ? mem : {};
  const t = num(obs[19], 0);
  const tors = num(obs[0], 0), spin = num(obs[1], 0), vx = num(obs[2], 0);

  // leaky integral of torso lean, time-step from the clock (fallback 1/60)
  let dt = 1 / 60;
  if (typeof M.lastT === 'number') {
    const d = t - M.lastT;
    if (d > 0 && d < 0.2) dt = d;
  }
  if (typeof M.lastT !== 'number' || t < M.lastT) M.I = 0;
  M.lastT = t;
  let I = typeof M.I === 'number' ? M.I : 0;
  I = I * (1 - dt / 2) + tors * dt;
  I = clamp(I, -2, 2);
  if (!isFinite(I)) I = 0;
  M.I = I;

  const a = Math.max(num(obs[15], 0), num(obs[16], 0));
  const hz = clamp((a - 0.1) / 0.15, 0, 1);
  const ph = 2 * Math.PI * f * t;
  const idx = [5, 10];
  const out = [];
  for (let L = 0; L < 2; L++) {
    const p = L === 0 ? ph : ph + phB;
    const hip = num(obs[idx[L]], 0), hipV = num(obs[idx[L] + 1], 0);
    const knee = num(obs[idx[L] + 2], 0), kneeV = num(obs[idx[L] + 3], 0);
    const s = Math.sin(p), c = Math.sin(p + phK);
    const kc = c * (1 - kr) + Math.max(0, c) * kr;
    let hipT = hip0 + hipAmp * s + hip2 * Math.sin(2 * p) + bal * tors + balSpin * spin + balV * vx + bi * I;
    let kneeT = knee0 + kneeAmp * kc + kneeBal * tors - kh * hz * Math.max(0, c);
    hipT = clamp(hipT, -0.9, 1.2);
    kneeT = clamp(kneeT, -1.7, -0.05);
    let uh = kp * (hipT - hip) - kd * hipV;
    let uk = kp * (kneeT - knee) - kd * kneeV;
    uh = clamp(uh, -1, 1);
    uk = clamp(uk, -1, 1);
    if (!isFinite(uh)) uh = 0;
    if (!isFinite(uk)) uk = 0;
    out.push(uh, uk);
  }
  return out;
}

function learn(lab) {
  const clamp01 = v => (v < 0 ? 0 : (v > 1 ? 1 : v));
  const keys = ['f', 'hip0', 'hipAmp', 'hip2', 'knee0', 'kneeAmp', 'kr', 'phK', 'phB',
                'kp', 'kd', 'bal', 'balSpin', 'balV', 'kneeBal', 'kh', 'bi'];
  const lo = [0.6, -0.6, -1.0, -0.6, -1.5, -1.0, 0, -Math.PI, -Math.PI, 3, 0, -2, -0.5, -0.2, -1.0, 0, -1.5];
  const hi = [3.0, 0.6, 1.0, 0.6, -0.1, 1.0, 1, Math.PI, Math.PI, 14, 1.0, 2, 0.5, 0.2, 1.0, 0.6, 1.5];
  const D = keys.length;

  const hasDate = (typeof Date !== 'undefined');
  const t0 = hasDate ? Date.now() : 0;
  const timeUp = () => hasDate && (Date.now() - t0 > 150000);

  const toP = x => {
    const o = {};
    for (let i = 0; i < D; i++) o[keys[i]] = lo[i] + clamp01(x[i]) * (hi[i] - lo[i]);
    return o;
  };
  const toX = p => keys.map((k, i) => {
    const v = (p && typeof p[k] === 'number' && isFinite(p[k])) ? p[k] : (lo[i] + hi[i]) / 2;
    return clamp01((v - lo[i]) / (hi[i] - lo[i]));
  });

  const left = () => {
    try { return lab.trialsLeft() > 0 && !timeUp(); } catch (e) { return false; }
  };

  let bestF = -Infinity, bestX = null, bestP = null;
  const elite = [];

  const evalX = x => {
    if (!left()) return null;
    const p = toP(x);
    let fit = -1;
    try {
      const r = lab.trial(p);
      if (r && typeof r.distance === 'number' && isFinite(r.distance)) {
        if (r.outcome === 'invalid' || r.outcome === 'error') fit = -1;
        else fit = r.distance * (r.outcome === 'fell' ? 0.85 : 1);
      }
    } catch (e) {
      fit = -1;
    }
    elite.push({ x: x.slice(), f: fit });
    if (fit > bestF) { bestF = fit; bestX = x.slice(); bestP = p; }
    return fit;
  };

  const gauss = () => {
    let u = 0;
    while (u === 0) u = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());
  };

  const randomX = () => {
    const x = [];
    for (let j = 0; j < D; j++) x.push(Math.random());
    return x;
  };

  // Separable CMA-ES (diagonal covariance) on the unit cube
  const cmaRun = (m0, sig0, lam, maxEvals) => {
    const N = D;
    const mu = Math.floor(lam / 2);
    const w = [];
    let ws = 0;
    for (let i = 0; i < mu; i++) { w.push(Math.log(mu + 0.5) - Math.log(i + 1)); ws += w[i]; }
    for (let i = 0; i < mu; i++) w[i] /= ws;
    const mueff = 1 / w.reduce((s, v) => s + v * v, 0);
    const cc = (4 + mueff / N) / (N + 4 + 2 * mueff / N);
    const cs = (mueff + 2) / (N + mueff + 5);
    const c1 = 2 / ((N + 1.3) * (N + 1.3) + mueff);
    const cmu = Math.min(1 - c1, 2 * (mueff - 2 + 1 / mueff) / ((N + 2) * (N + 2) + mueff));
    const c1s = (N + 2) / 3 * c1;
    const cms = Math.min(1 - c1s, (N + 2) / 3 * cmu);
    const damps = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (N + 1)) - 1) + cs;
    const chiN = Math.sqrt(N) * (1 - 1 / (4 * N) + 1 / (21 * N * N));

    let m = m0.slice();
    let sig = sig0;
    const d = new Array(N).fill(1);
    const pc = new Array(N).fill(0);
    const ps = new Array(N).fill(0);
    let used = 0, gen = 0, runBest = -Infinity, stall = 0;

    while (used < maxEvals && left()) {
      gen++;
      const pop = [];
      let stop = false;
      for (let k = 0; k < lam; k++) {
        const y = [];
        for (let j = 0; j < N; j++) y.push(Math.sqrt(d[j]) * gauss());
        const x = m.map((mv, j) => clamp01(mv + sig * y[j]));
        const yAct = x.map((xv, j) => (xv - m[j]) / sig);
        const fit = evalX(x);
        if (fit === null) { stop = true; break; }
        used++;
        pop.push({ x: x, y: yAct, f: fit });
        if (used >= maxEvals) break;
      }
      if (pop.length < mu) break;
      pop.sort((a, b) => b.f - a.f);

      const mOld = m.slice();
      const yw = new Array(N).fill(0);
      for (let i = 0; i < mu; i++) for (let j = 0; j < N; j++) yw[j] += w[i] * pop[i].y[j];
      m = mOld.map((mv, j) => clamp01(mv + sig * yw[j]));
      const yE = m.map((mv, j) => (mv - mOld[j]) / sig);

      for (let j = 0; j < N; j++) {
        ps[j] = (1 - cs) * ps[j] + Math.sqrt(cs * (2 - cs) * mueff) * yE[j] / Math.sqrt(d[j]);
      }
      let psN2 = 0;
      for (let j = 0; j < N; j++) psN2 += ps[j] * ps[j];
      const psN = Math.sqrt(psN2);
      const hsig = (psN / Math.sqrt(1 - Math.pow(1 - cs, 2 * gen)) / chiN) < (1.4 + 2 / (N + 1)) ? 1 : 0;
      for (let j = 0; j < N; j++) {
        pc[j] = (1 - cc) * pc[j] + hsig * Math.sqrt(cc * (2 - cc) * mueff) * yE[j];
      }
      for (let j = 0; j < N; j++) {
        let rank = 0;
        for (let i = 0; i < mu; i++) rank += w[i] * pop[i].y[j] * pop[i].y[j];
        d[j] = (1 - c1s - cms) * d[j] + c1s * (pc[j] * pc[j] + (1 - hsig) * cc * (2 - cc) * d[j]) + cms * rank;
        if (!(d[j] > 1e-10)) d[j] = 1e-10;
        if (d[j] > 4) d[j] = 4;
      }
      sig *= Math.exp((cs / damps) * (psN / chiN - 1));
      sig = Math.min(1, Math.max(1e-6, sig));

      if (pop[0].f > runBest + 1e-9) { runBest = pop[0].f; stall = 0; }
      else stall++;

      let maxSd = 0;
      for (let j = 0; j < N; j++) maxSd = Math.max(maxSd, Math.sqrt(d[j]));
      if (stall >= 15 || sig * maxSd < 1e-4 || stop) break;
    }
  };

  // Seeds: attempt-7 params (the 4.39 m gait) with no integrator, then attempt-5 and attempt-3 gaits
  const seeds = [
    { f: 1.7056679600110205, hip0: 0.23867247322167118, hipAmp: 0.6494665573512484, hip2: -0.045850731665852296,
      knee0: -1.4429405969254219, kneeAmp: -0.156685958793936, kr: 0.3298731802450007, phK: 0.20064237738610124,
      phB: 2.2049660559765245, kp: 4.673907672232365, kd: 0.22453849680429874, bal: 0.8861097357856784,
      balSpin: 0.45306905397533936, balV: 0.09355540367727411, kneeBal: -0.20053342231026416, kh: 0.5841175469736977,
      bi: 0 },
    { f: 1.6239765, hip0: 0.1263182, hipAmp: 0.7002466, hip2: 0.1992154, knee0: -1.4089631, kneeAmp: -0.1326225,
      kr: 0.3521385, phK: -0.1399451, phB: 2.6736328, kp: 3.6210435, kd: 0.2441899, bal: 1.1839601,
      balSpin: 0.4945270, balV: 0.1190603, kneeBal: -0.0001745, kh: 0.5920344, bi: 0 },
    { f: 2.1368828, hip0: 0.31202, hipAmp: 0.76861, hip2: 0, knee0: -1.33622, kneeAmp: 0.42078, kr: 0.37,
      phK: 2.02378, phB: 2.61665, kp: 7.2047, kd: 0.26315, bal: 1.80076, balSpin: 0.48708, balV: 0.13399,
      kneeBal: 0, kh: 0.35, bi: 0 }
  ];

  for (const s of seeds) {
    if (!left()) break;
    evalX(toX(s));
  }

  // Structured scan around the best: frequency, leg phase, knee amplitude
  if (bestX && left()) {
    const base = bestX.slice();
    const fw = hi[0] - lo[0];
    const pw = hi[8] - lo[8];
    const aw = hi[5] - lo[5];
    const moves = [
      [0.25, 0, 0], [-0.25, 0, 0], [0.45, 0, 0], [-0.45, 0, 0],
      [0, 0.6, 0], [0, -0.6, 0], [0, 0, 0.3], [0, 0, -0.3],
      [0.25, 0.6, 0], [0.25, -0.6, 0], [-0.25, 0.6, 0], [-0.25, -0.6, 0]
    ];
    for (const [df, dph, dk] of moves) {
      if (!left()) break;
      const x = base.slice();
      x[0] = clamp01(x[0] + df / fw);
      x[8] = clamp01(x[8] + dph / pw);
      x[5] = clamp01(x[5] + dk / aw);
      evalX(x);
    }
  }

  // Integrator-gain scan around the best (new dimension, bi)
  if (bestX && left()) {
    const base = bestX.slice();
    const bw = hi[16] - lo[16];
    for (const db of [0.3, -0.3, 0.7, -0.7]) {
      if (!left()) break;
      const x = base.slice();
      x[16] = clamp01(x[16] + db / bw);
      evalX(x);
    }
  }

  // Local random samples around the best, then a few global samples
  if (bestX) {
    for (let i = 0; i < 40 && left(); i++) {
      const base = bestX.slice();
      evalX(base.map(v => clamp01(v + 0.1 * gauss())));
    }
  }
  for (let i = 0; i < 30 && left(); i++) evalX(randomX());

  // Refinement: CMA-ES restarts from the best, from elites, and from random points
  let k = 0;
  while (left()) {
    let m0, sig0, lam;
    const r = k % 4;
    if (r === 0) { m0 = bestX ? bestX.slice() : randomX(); sig0 = 0.06; lam = 12; }
    else if (r === 1) { m0 = bestX ? bestX.slice() : randomX(); sig0 = 0.15; lam = 16; }
    else if (r === 2) {
      const top = elite.slice().sort((a, b) => b.f - a.f).slice(0, 5);
      const pick = top.length ? top[Math.floor(Math.random() * top.length)].x : randomX();
      m0 = pick.slice(); sig0 = 0.1; lam = 14;
    }
    else { m0 = randomX(); sig0 = 0.3; lam = 24; }
    const runBudget = Math.min(150, lab.trialsLeft());
    if (runBudget < 6) break;
    cmaRun(m0, sig0, lam, runBudget);
    k++;
    if (k > 200) break;
  }

  if (bestP) return bestP;
  return toP(toX(seeds[0]));
}
